const NO_COUNT=new Set(["tokyo-0-2", "tokyo-0-4", "tokyo-1-4", "tokyo-2-2", "tokyo-2-5", "tokyo-3-1", "tokyo-3-4", "tokyo-4-3", "tokyo-5-3", "tokyo-6-2", "kyoto-0-2", "kyoto-1-3", "kyoto-4-5", "osaka-0-2", "food-tokyo-0", "food-tokyo-1", "food-tokyo-3", "food-tokyo-4", "food-tokyo-5", "food-tokyo-6", "food-tokyo-7", "food-tokyo-8", "food-tokyo-9", "food-tokyo-10", "food-tokyo-11", "food-tokyo-12", "food-tokyo-13", "food-tokyo-14", "food-tokyo-16", "food-tokyo-17", "food-tokyo-18", "food-tokyo-19", "food-tokyo-20", "food-tokyo-21", "food-tokyo-22", "food-kyoto-0", "food-kyoto-1", "food-osaka-1"]);
const TICK_IT=document.documentElement.lang==='it',boxes=[...document.querySelectorAll('[data-stop]')],key='frolicking-nicky-japan-v1';let state={};try{state=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{}for(const box of boxes)box.checked=state[box.dataset.stop]===true;function update(){const done=boxes.filter(b=>b.checked&&!NO_COUNT.has(b.dataset.stop)).length;document.querySelector('#vn-count').textContent=done+' / '+boxes.filter(b=>!NO_COUNT.has(b.dataset.stop)).length+(TICK_IT?' completati':' completed');const progress=document.querySelector('#vn-progress');progress.max=boxes.filter(b=>!NO_COUNT.has(b.dataset.stop)).length;progress.value=done}function save(){const data=Object.fromEntries(boxes.map(b=>[b.dataset.stop,b.checked]));try{localStorage.setItem(key,JSON.stringify(data));document.querySelector('#vn-save').textContent=(TICK_IT?'Le tue spunte restano su questo dispositivo.':'Your ticks stay on this device.')}catch{document.querySelector('#vn-save').textContent=(TICK_IT?'Il salvataggio non è disponibile; le spunte funzionano finché resti su questa pagina.':'Saving is unavailable; ticks work until you leave this page.')}update()}boxes.forEach(b=>b.addEventListener('change',save));document.querySelector('.vn-reset').addEventListener('click',()=>{if(confirm((TICK_IT?'Azzerare la checklist del Giappone?':'Clear your Japan checklist?'))){boxes.forEach(b=>b.checked=false);save()}});update();